    pub fn connecting(&self) -> bool {
        match self.link {
            Link::Connecting => true,
            Link::Ready => self.session.workspace_name.is_empty(),
            Link::Crashed { .. } => false,
        }
    }

    pub fn apply(&mut self, event: Event) {
        let content = matches!(
            event,
            Event::AssistantDelta { .. }
                | Event::ToolStart { .. }
                | Event::ToolEnd { .. }
                | Event::FileDiff { .. }
                | Event::TurnResult { .. }
                | Event::Notice { .. }
                | Event::SlashResult { .. }
                | Event::SteerAck { .. }
                | Event::History { .. }
        );
        self.apply_event(event);
        self.promote_pending_approval();
        if self.submit_when_ready && self.link == Link::Ready && !self.connecting() {
            self.submit_when_ready = false;
            if let Some(action) = self.submit() {
                self.outbox.push(action);
            }
        }
        if content && self.scroll_back > 0 {
            self.unseen = true;
        }
    }

    fn apply_event(&mut self, event: Event) {
        // Provider output or a tool starting means the stream is not silent any more.
